//! Checks against reference values from independent implementations: empyrical for the return
//! statistics, SciPy for quantiles, and numerical integration for the Cornish–Fisher expected
//! shortfall. The fixture is generated by `scripts/reference/risk_statistics.py`.

#![allow(clippy::unwrap_used)]

use finalytics_risk::*;
use serde_json::Value;

const FIXTURE: &str = include_str!("fixtures/statistics.json");

fn fixture() -> Value {
    serde_json::from_str(FIXTURE).unwrap()
}

fn floats(value: &Value) -> Vec<f64> {
    value
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_f64().unwrap())
        .collect()
}

#[track_caller]
fn close(actual: f64, expected: f64, tolerance: f64, what: &str) {
    let scale = expected.abs().max(1.0);
    assert!(
        (actual - expected).abs() <= tolerance * scale,
        "{what}: {actual} against the reference {expected}"
    );
}

#[test]
fn normal_quantiles() {
    for pair in fixture()["normal_quantile"].as_array().unwrap() {
        let [p, x] = floats(pair)[..] else { panic!() };
        close(normal_quantile(p), x, 1e-14, &format!("quantile at {p}"));
    }
}

#[test]
fn statistics_match_the_reference() {
    for case in fixture()["cases"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let options: StatisticsOptions = serde_json::from_value(case["options"].clone()).unwrap();
        let returns = floats(&case["returns"]);
        let benchmark = floats(&case["benchmark"]);

        let stats = statistics(&returns, &options).unwrap();
        let expected = &case["statistics"];
        let check = |field: &str, actual: f64| {
            close(
                actual,
                expected[field].as_f64().unwrap(),
                1e-11,
                &format!("{name} {field}"),
            );
        };
        check("total_return", stats.total_return);
        check("annualised_return", stats.annualised_return);
        check("volatility", stats.volatility);
        check("downside_deviation", stats.downside_deviation);
        check("sharpe_ratio", stats.sharpe_ratio.unwrap());
        check("sortino_ratio", stats.sortino_ratio.unwrap());
        check("max_drawdown", stats.max_drawdown);
        check("calmar_ratio", stats.calmar_ratio.unwrap());
        check("skewness", stats.skewness.unwrap());
        check("excess_kurtosis", stats.excess_kurtosis.unwrap());

        let relative = relative_statistics(&returns, &benchmark, &options).unwrap();
        let expected = &case["relative"];
        let check = |field: &str, actual: f64| {
            close(
                actual,
                expected[field].as_f64().unwrap(),
                1e-11,
                &format!("{name} {field}"),
            );
        };
        check("active_return", relative.active_return);
        check("tracking_error", relative.tracking_error);
        check("information_ratio", relative.information_ratio.unwrap());
        check("beta", relative.beta.unwrap());
        check("alpha", relative.alpha.unwrap());
        check("correlation", relative.correlation.unwrap());
    }
}

#[test]
fn tail_risk_matches_the_reference() {
    for case in fixture()["cases"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let returns = floats(&case["returns"]);
        for expected in case["tail"].as_array().unwrap() {
            let confidence = expected["confidence"].as_f64().unwrap();
            for (key, method) in [
                ("historical", TailMethod::Historical),
                ("parametric", TailMethod::Parametric),
                ("cornish_fisher", TailMethod::CornishFisher),
            ] {
                let [var, es] = floats(&expected[key])[..] else {
                    panic!()
                };
                let tail = tail_risk(&returns, confidence, method).unwrap();
                let what = format!("{name} {key} at {confidence}");
                close(
                    tail.value_at_risk,
                    var,
                    1e-12,
                    &format!("{what}: value at risk"),
                );
                close(
                    tail.expected_shortfall,
                    es,
                    1e-10,
                    &format!("{what}: expected shortfall"),
                );
                assert!(tail.expected_shortfall >= tail.value_at_risk, "{what}");
            }
        }
    }
}
